Object.assign(TRANSLATIONS, TRANSLATIONS_EXTRA);

// ---------------------------------------------------------------------------
// Engine
// ---------------------------------------------------------------------------

// The active UI language always comes from the CURRENTLY LOGGED-IN user's
// own profile — never the language of whoever last edited someone else
// (e.g. an Admin changing another player's preferredLanguage doesn't touch
// the Admin's own interface; it only takes effect for that player the next
// time their profile loads, per the localization spec's Admin section).
function currentLocale() {
  const code = (typeof Store !== "undefined" && Store.currentUser && Store.currentUser.preferredLanguage) || DEFAULT_LANGUAGE_CODE;
  return TRANSLATIONS[code] ? code : DEFAULT_LANGUAGE_CODE;
}

// t("home.eyebrow") walks TRANSLATIONS[locale].home.eyebrow. Falls back to
// the English dictionary key-by-key (not just whole-locale) so a locale
// that's missing one newer key still shows real English text instead of
// "undefined" or the raw key — see requirement #11 (never show the user a
// key name).
function t(key) {
  const locale = currentLocale();
  const walk = (dict) => key.split(".").reduce((acc, part) => (acc && typeof acc === "object" ? acc[part] : undefined), dict);
  const hit = walk(TRANSLATIONS[locale]);
  if (typeof hit === "string") return hit;
  const fallback = walk(TRANSLATIONS.en);
  if (typeof fallback === "string") return fallback;
  // Should never happen (every key used in app.js has an English entry
  // above) — but if a key is ever mistyped, fail visibly-but-harmlessly
  // rather than crash the render.
  console.warn("i18n: missing translation key", key);
  return "";
}

// Sets <html dir="rtl"|"ltr"> for the active locale (Arabic only, per the
// localization spec's RTL requirement) and stamps the locale as a lang
// attribute for accessibility/CSS hooks. Called every time the shell
// re-renders, so it always reflects whichever profile is currently signed
// in (and reverts to "en"/"ltr" once signed out).
function applyDocumentDirection() {
  const locale = currentLocale();
  const info = (typeof languageInfo === "function") ? languageInfo(locale) : null;
  document.documentElement.dir = info && info.rtl ? "rtl" : "ltr";
  document.documentElement.lang = locale;
}

// Called after My Account (or Admin, for their own row) saves a new
// preferredLanguage — re-renders the whole shell+current page immediately
// under the new locale, with no sign-out/sign-in round trip. Safe to call
// any time; a no-op flicker at worst if the locale didn't actually change.
function applyLocaleAndRerender() {
  applyDocumentDirection();
  renderShell();
  router();
}
